			                var flag1 = false;
			                var flag2 = false;
			                //입력시
			                flag1 = checkDuplicate(dsDormitList.getRowCountByState(cpr.data.tabledata.RowState.INSERTED)[2], dsDormitList.getRowIndicesByState(cpr.data.tabledata.RowState.INSERTED)[2]);
